/**
 * Makes the repo-root tsconfig.json parseable when only `website/` is installed.
 *
 * Vite walks up from `website/` looking for a parent "solution" tsconfig and parses
 * every tsconfig.json it finds on the way. It finds the repo-root one, which is
 * generated by expo-module-scripts and starts with:
 *
 *   { "extends": "expo-module-scripts/tsconfig.base" }
 *
 * That package is a devDependency of the npm package at the repo root, not of this
 * site. Any build that installs only `website/`'s dependencies — Vercel with its root
 * directory set to `website`, for instance — has no way to resolve the extends chain,
 * and `astro sync` fails with "Tsconfig not found expo-module-scripts/tsconfig.base".
 *
 * Nothing in the docs build reads that config; it just has to resolve. So when the real
 * package is missing, drop a minimal stand-in next to where it would have been. When the
 * repo root is fully installed (any normal dev checkout) this is a no-op.
 *
 * Reproduce the failure locally with:
 *   mv ../node_modules/expo-module-scripts /tmp && npm run build
 */
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const websiteDir = dirname(dirname(fileURLToPath(import.meta.url)));
const packageDir = join(websiteDir, '..', 'node_modules', 'expo-module-scripts');

if (existsSync(join(packageDir, 'tsconfig.base.json'))) {
  process.exit(0);
}

mkdirSync(packageDir, { recursive: true });

// The `exports` map mirrors the real package's `"./tsconfig.*": "./tsconfig.*.json"`
// entry, which is how `expo-module-scripts/tsconfig.base` resolves to a file.
writeFileSync(
  join(packageDir, 'package.json'),
  JSON.stringify(
    {
      name: 'expo-module-scripts',
      version: '0.0.0-tsconfig-stub',
      exports: { './tsconfig.*': './tsconfig.*.json' },
    },
    null,
    2,
  ) + '\n',
);

writeFileSync(
  join(packageDir, 'tsconfig.base.json'),
  JSON.stringify({ compilerOptions: {} }, null, 2) + '\n',
);

console.log(
  '[docs] stubbed expo-module-scripts/tsconfig.base so the repo-root tsconfig.json resolves',
);
